    sy0,sx0=min(ys),min(xs); H=max(y for y,_ in zip(ys,xs))-sy0+1; W=max(x for _,x in zip(ys,xs))-sx0+1
    rel=[(y-sy0,x-sx0) for y,x in zip(ys,xs)]
    n,m=Ai.shape
    # candidate positions: pattern fits on 0-cells of input
    cands=[]
    for sy in range(n-H+1):
        for sx in range(m-W+1):
            if all(Ai[sy+a,sx+b]==0 for a,b in rel): cands.append((sy,sx))
    Os=set(zip(*np.where(Oi==shp)))
    comps=[]; used=set()
    for cell in Os:
        if cell in used: continue
        st=[cell]; comp=set(); used.add(cell)
        while st:
            c=st.pop(); comp.add(c)
            for dy in (-1,0,1):
                for dx in (-1,0,1):
                    n2=(c[0]+dy,c[1]+dx)
                    if n2 in Os and n2 not in comp and n2 not in used:
                        used.add(n2); st.append(n2)
        comps.append(comp)
    good=[]
    for comp in comps:
        cs=sorted(comp); r0,c0=cs[0]
        occ={(y-r0,x-c0) for y,x in comp}
        if occ<=set(rel): good.append((r0,c0,len(comp)))
    print(f'demo{p}: pattern rel={rel}; cands_on_0={len(cands)}; exact-stamp-comps={good}')
    return cands,good
for p in [1,2,3,4]: analyze(p)

def f(A):
    A=np.array(A); n,m=A.shape
    cnt=Counter(A.flatten().tolist()); shp=min(cnt.items(), key=lambda kv:kv[1])[0]
    ys,xs=np.where(A==shp)
    sy0,sx0=min(ys),min(xs); H=max(y for y,_ in zip(ys,xs))-sy0+1; W=max(x for _,x in zip(ys,xs))-sx0+1
    rel=[(y-sy0,x-sx0) for y,x in zip(ys,xs)]
    out=A.copy()
    for sy in range(n-H+1):
        for sx in range(m-W+1):
            if not all(A[sy+a,sx+b]==0 for a,b in rel): continue
            for a,b in rel:
                out[sy+a,sx+b]=shp
    return out
for p in [1,2,3,4]:
    Ai=np.array(G[f'Demo pair {p} input']); Oi=np.array(G[f'Demo pair {p} output'])
    print(f'demo{p}:', np.array_equal(f(Ai.tolist()),Oi))
